package site.hsu.hub.recruitment.application;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import site.hsu.hub.club.api.ClubRecruitmentSummaryReader;import site.hsu.hub.recruitment.adapter.out.persistence.*;import site.hsu.hub.recruitment.domain.*;import java.time.Instant;import java.util.*;
@Service public class RecruitmentSummaryService implements ClubRecruitmentSummaryReader{
 private final RecruitmentRepository recruitments;public RecruitmentSummaryService(RecruitmentRepository recruitments){this.recruitments=recruitments;}
 @Transactional(readOnly=true)public Map<Long,Summary>currentForClubs(Iterable<Long>ids,Instant now){List<Long>list=new ArrayList<>();ids.forEach(list::add);if(list.isEmpty())return Map.of();Map<Long,RecruitmentEntity>selected=new HashMap<>();for(var r:recruitments.findByClubIdIn(list))selected.merge(r.clubId(),r,(a,b)->better(a,b,now));Map<Long,Summary>result=new HashMap<>();selected.forEach((club,r)->result.put(club,new Summary(r.id(),new RecruitmentPeriod(r.opensAt(),r.closesAt()).stateAt(now).name(),r.opensAt(),r.closesAt())));return result;}
 private static RecruitmentEntity better(RecruitmentEntity a,RecruitmentEntity b,Instant now){var as=new RecruitmentPeriod(a.opensAt(),a.closesAt()).stateAt(now);var bs=new RecruitmentPeriod(b.opensAt(),b.closesAt()).stateAt(now);int ap=priority(as),bp=priority(bs);return bp>ap||(bp==ap&&b.publishedAt().isAfter(a.publishedAt()))?b:a;}private static int priority(RecruitmentState s){return switch(s){case OPEN->3;case SCHEDULED->2;case CLOSED->1;};}
}
